const releaseStockBalance = `-- name: ReleaseStockBalance :one
UPDATE inv.stock_balance
SET reserved_qty = GREATEST(reserved_qty - $2, 0),
    updated_by = $3
WHERE id = $1 AND deleted_at IS NULL
RETURNING row_version
`

