const upsertMasterdataCache = `-- name: UpsertMasterdataCache :exec
INSERT INTO inv.masterdata_cache (organization_id, party_id, code, name, party_type)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (organization_id, party_id) DO UPDATE
SET code = EXCLUDED.code, name = EXCLUDED.name, party_type = EXCLUDED.party_type, updated_at = now()
`

type UpsertMasterdataCacheParams struct {
	OrganizationID uuid.UUID `json:"organization_id"`
	PartyID        uuid.UUID `json:"party_id"`
	Code           string    `json:"code"`
	Name           string    `json:"name"`
	PartyType      string    `json:"party_type"`
}

func (q *Queries) UpsertMasterdataCache(ctx context.Context, arg UpsertMasterdataCacheParams) error {
	_, err := q.db.Exec(ctx, upsertMasterdataCache,
		arg.OrganizationID,
		arg.PartyID,
		arg.Code,
		arg.Name,
		arg.PartyType,
	)
	return err
}

const upsertReceiptBalance = `-- name: UpsertReceiptBalance :one
INSERT INTO inv.stock_balance (
    organization_id, warehouse_id, item_id, on_hand_qty, reserved_qty, avg_cost, created_by
) VALUES ($1, $2, $3, $4, 0, $5, $6)
ON CONFLICT (organization_id, warehouse_id, item_id) DO UPDATE
SET on_hand_qty = inv.stock_balance.on_hand_qty + EXCLUDED.on_hand_qty,
    avg_cost = CASE
        WHEN EXCLUDED.avg_cost > 0 THEN EXCLUDED.avg_cost
        ELSE inv.stock_balance.avg_cost
    END,
    updated_by = $6
RETURNING id, warehouse_id, item_id, on_hand_qty, reserved_qty, available_qty, avg_cost, row_version
`

type UpsertReceiptBalanceParams struct {
	OrganizationID uuid.UUID      `json:"organization_id"`
	WarehouseID    uuid.UUID      `json:"warehouse_id"`
	ItemID         uuid.UUID      `json:"item_id"`
	OnHandQty      pgtype.Numeric `json:"on_hand_qty"`
	AvgCost        pgtype.Numeric `json:"avg_cost"`
	CreatedBy      uuid.UUID      `json:"created_by"`
}

type UpsertReceiptBalanceRow struct {
	ID           uuid.UUID      `json:"id"`
	WarehouseID  uuid.UUID      `json:"warehouse_id"`
	ItemID       uuid.UUID      `json:"item_id"`
	OnHandQty    pgtype.Numeric `json:"on_hand_qty"`
	ReservedQty  pgtype.Numeric `json:"reserved_qty"`
	AvailableQty pgtype.Numeric `json:"available_qty"`
	AvgCost      pgtype.Numeric `json:"avg_cost"`
	RowVersion   int32          `json:"row_version"`
}

func (q *Queries) UpsertReceiptBalance(ctx context.Context, arg UpsertReceiptBalanceParams) (UpsertReceiptBalanceRow, error) {
	row := q.db.QueryRow(ctx, upsertReceiptBalance,
		arg.OrganizationID,
		arg.WarehouseID,
		arg.ItemID,
		arg.OnHandQty,
		arg.AvgCost,
		arg.CreatedBy,
	)
	var i UpsertReceiptBalanceRow
	err := row.Scan(
		&i.ID,
		&i.WarehouseID,
		&i.ItemID,
		&i.OnHandQty,
		&i.ReservedQty,
		&i.AvailableQty,
		&i.AvgCost,
		&i.RowVersion,
	)
	return i, err
}
